Just for reference... this is a microbenchmark, so take this with a grain of salt, but:
```C#
    private List<int> _list;

    [Params(1, 10)]
    public int Count { get; set; }

    [GlobalSetup]
    public void Setup()
    {
        _list = new List<int>(Enumerable.Range(42, Count));
    }

    [Benchmark]
    public int Sum1()
    {
        List<int> list = _list;
        if (list.Count == 1)
        {
            return list[0];
        }
        else
        {
            int sum = 0;
            foreach (int i in CollectionsMarshal.AsSpan(list))
            {
                sum += i;
            }
            return sum;
        }
    }

    [Benchmark]
    public int Sum2()
    {
        int sum = 0;
        foreach (int i in _list)
        {
            sum += i;
        }
        return sum;
    }

    [Benchmark]
    public int Sum3()
    {
        int sum = 0;
        foreach (int i in CollectionsMarshal.AsSpan(_list))
        {
            sum += i;
        }
        return sum;
    }
```
on my machine produces:

| Method | Count |       Mean |     Error |
|------- |------ |-----------:|----------:|
|   Sum1 |     1 |  0.2687 ns | 0.0069 ns |
|   Sum2 |     1 |  2.5162 ns | 0.0643 ns |
|   Sum3 |     1 |  0.7283 ns | 0.0217 ns |
|   Sum1 |    10 |  3.5858 ns | 0.0303 ns |
|   Sum2 |    10 | 12.5352 ns | 0.0425 ns |
|   Sum3 |    10 |  3.9256 ns | 0.0141 ns |

> By the way if there's any other data structure that SparseIntMap could use for the dense part that would be better for performance, it might be worth reworking it.

I think the only thing that would be _slightly_ better would be just managing an array and int length directly ourselves.  It should be a simple and contained enough change that I can just do that.
